edits.find:
flex-direction: column;

${({ theme }) => theme.breakpoints.desktop} {
  flex-direction: row;
  justify-content: end;
  align-items: center;
  margin-top: 67px;

  > :first-child {
    order: 2;
  }

  > :last-child {
    order: 1;
  }
}

edits.replace:
flex-direction: column-reverse;

${({ theme }) => theme.breakpoints.desktop} {
  flex-direction: row;
  justify-content: end;
  align-items: center;
  margin-top: 67px;
}
